"""
generate_embedded.py
Creates app_embedded.py — no templates/ folder needed.
"""
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
APP_PY = os.path.join(HERE, "app.py")
OUT    = os.path.join(HERE, "app_embedded.py")

if not os.path.exists(APP_PY):
    print("ERROR: app.py not found in", HERE)
    sys.exit(1)

HTML_PAGE = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>\n  <title>RamaPlot — Ramachandran Plot Analyzer</title>\n  <style>\n    @import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap\');\n\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n    :root {\n      --bg: #f7f9fc;\n      --surface: #ffffff;\n      --surface2: #f0f4f8;\n      --border: #e2e8f0;\n      --accent: #2563eb;\n      --accent2: #0ea5e9;\n      --accent-dark: #1d4ed8;\n      --text: #0f172a;\n      --text2: #475569;\n      --text3: #94a3b8;\n      --success: #059669;\n      --warning: #d97706;\n      --danger: #dc2626;\n      --shadow: 0 4px 24px rgba(37,99,235,0.08);\n      --shadow-lg: 0 12px 40px rgba(37,99,235,0.13);\n    }\n\n    html, body {\n      height: 100%;\n      font-family: \'Inter\', sans-serif;\n      background: var(--bg);\n      color: var(--text);\n      overflow-x: hidden;\n    }\n\n    /* ── Animated protein background canvas ── */\n    #bg-canvas {\n      position: fixed;\n      top: 0; left: 0;\n      width: 100%; height: 100%;\n      z-index: 0;\n      pointer-events: none;\n      opacity: 0.18;\n    }\n\n    /* ── Layout ── */\n    .app {\n      position: relative;\n      z-index: 1;\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n    }\n\n    /* ── Header ── */\n    header {\n      background: rgba(255,255,255,0.92);\n      backdrop-filter: blur(16px);\n      border-bottom: 1px solid var(--border);\n      padding: 0 2rem;\n      height: 64px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      position: sticky;\n      top: 0;\n      z-index: 100;\n      box-shadow: 0 2px 12px rgba(37,99,235,0.06);\n    }\n\n    .logo {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      text-decoration: none;\n    }\n\n    .logo-icon {\n      width: 36px; height: 36px;\n      background: linear-gradient(135deg, #2563eb, #0ea5e9);\n      border-radius: 10px;\n      display: flex; align-items: center; justify-content: center;\n      font-size: 18px;\n      box-shadow: 0 2px 8px rgba(37,99,235,0.35);\n    }\n\n    .logo-text {\n      font-size: 1.25rem;\n      font-weight: 700;\n      color: var(--text);\n      letter-spacing: -0.5px;\n    }\n\n    .logo-text span { color: var(--accent); }\n\n    .header-badge {\n      font-size: 0.7rem;\n      font-weight: 600;\n      background: linear-gradient(90deg, #2563eb22, #0ea5e922);\n      color: var(--accent);\n      border: 1px solid #2563eb33;\n      padding: 3px 10px;\n      border-radius: 999px;\n      letter-spacing: 0.5px;\n    }\n\n    /* ── Main ── */\n    main {\n      flex: 1;\n      max-width: 1100px;\n      margin: 0 auto;\n      padding: 2rem 1.5rem 4rem;\n      width: 100%;\n    }\n\n    /* ── Hero ── */\n    .hero {\n      text-align: center;\n      margin-bottom: 2.5rem;\n    }\n\n    .hero h1 {\n      font-size: 2.2rem;\n      font-weight: 700;\n      color: var(--text);\n      letter-spacing: -1px;\n      line-height: 1.2;\n      margin-bottom: 0.6rem;\n    }\n\n    .hero h1 span {\n      background: linear-gradient(90deg, #2563eb, #0ea5e9);\n      -webkit-background-clip: text;\n      -webkit-text-fill-color: transparent;\n      background-clip: text;\n    }\n\n    .hero p {\n      color: var(--text2);\n      font-size: 1rem;\n      max-width: 520px;\n      margin: 0 auto;\n      line-height: 1.6;\n    }\n\n    /* ── Input card ── */\n    .input-card {\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: 20px;\n      padding: 2rem;\n      box-shadow: var(--shadow);\n      margin-bottom: 2rem;\n    }\n\n    .input-tabs {\n      display: flex;\n      gap: 6px;\n      margin-bottom: 1.6rem;\n      background: var(--surface2);\n      padding: 5px;\n      border-radius: 12px;\n      width: fit-content;\n    }\n\n    .tab-btn {\n      padding: 7px 20px;\n      border: none;\n      border-radius: 9px;\n      font-size: 0.875rem;\n      font-weight: 500;\n      cursor: pointer;\n      transition: all 0.2s;\n      background: transparent;\n      color: var(--text2);\n      font-family: \'Inter\', sans-serif;\n    }\n\n    .tab-btn.active {\n      background: var(--surface);\n      color: var(--accent);\n      box-shadow: 0 2px 8px rgba(37,99,235,0.12);\n      font-weight: 600;\n    }\n\n    .tab-panel { display: none; }\n    .tab-panel.active { display: block; }\n\n    .input-row {\n      display: flex;\n      gap: 12px;\n      align-items: flex-end;\n    }\n\n    .input-group {\n      flex: 1;\n    }\n\n    .input-group label {\n      display: block;\n      font-size: 0.8rem;\n      font-weight: 600;\n      color: var(--text2);\n      margin-bottom: 6px;\n      letter-spacing: 0.3px;\n      text-transform: uppercase;\n    }\n\n    .input-field {\n      width: 100%;\n      padding: 10px 14px;\n      border: 1.5px solid var(--border);\n      border-radius: 10px;\n      font-size: 0.95rem;\n      font-family: \'JetBrains Mono\', monospace;\n      color: var(--text);\n      background: var(--bg);\n      transition: all 0.2s;\n      outline: none;\n    }\n\n    .input-field:focus {\n      border-color: var(--accent);\n      box-shadow: 0 0 0 3px rgba(37,99,235,0.1);\n      background: white;\n    }\n\n    .file-drop {\n      border: 2px dashed var(--border);\n      border-radius: 12px;\n      padding: 2rem;\n      text-align: center;\n      cursor: pointer;\n      transition: all 0.2s;\n      background: var(--bg);\n    }\n\n    .file-drop:hover, .file-drop.drag-over {\n      border-color: var(--accent);\n      background: rgba(37,99,235,0.03);\n    }\n\n    .file-drop-icon { font-size: 2rem; margin-bottom: 8px; }\n\n    .file-drop p {\n      color: var(--text2);\n      font-size: 0.875rem;\n      margin-bottom: 4px;\n    }\n\n    .file-drop small { color: var(--text3); font-size: 0.775rem; }\n\n    #file-input { display: none; }\n\n    .file-name {\n      display: none;\n      margin-top: 8px;\n      font-size: 0.8rem;\n      color: var(--success);\n      font-weight: 600;\n    }\n\n    .btn-analyze {\n      padding: 11px 28px;\n      background: linear-gradient(135deg, #2563eb, #0ea5e9);\n      color: white;\n      border: none;\n      border-radius: 10px;\n      font-size: 0.95rem;\n      font-weight: 600;\n      cursor: pointer;\n      transition: all 0.2s;\n      white-space: nowrap;\n      font-family: \'Inter\', sans-serif;\n      box-shadow: 0 4px 14px rgba(37,99,235,0.3);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .btn-analyze:hover {\n      transform: translateY(-1px);\n      box-shadow: 0 6px 20px rgba(37,99,235,0.38);\n    }\n\n    .btn-analyze:disabled {\n      opacity: 0.6;\n      cursor: not-allowed;\n      transform: none;\n    }\n\n    /* ── Loading ── */\n    .loading {\n      display: none;\n      text-align: center;\n      padding: 3rem;\n    }\n\n    .loading.active { display: block; }\n\n    .spinner {\n      width: 48px; height: 48px;\n      border: 4px solid var(--border);\n      border-top-color: var(--accent);\n      border-radius: 50%;\n      animation: spin 0.8s linear infinite;\n      margin: 0 auto 1rem;\n    }\n\n    @keyframes spin { to { transform: rotate(360deg); } }\n\n    .loading p { color: var(--text2); font-size: 0.95rem; }\n\n    /* ── Error ── */\n    .error-box {\n      display: none;\n      background: #fef2f2;\n      border: 1px solid #fecaca;\n      border-radius: 12px;\n      padding: 1rem 1.25rem;\n      color: var(--danger);\n      font-size: 0.9rem;\n      margin-bottom: 1.5rem;\n      display: none;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .error-box.active { display: flex; }\n\n    /* ── Results ── */\n    .results { display: none; }\n    .results.active { display: block; }\n\n    .results-header {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      margin-bottom: 1.5rem;\n      flex-wrap: gap;\n      gap: 12px;\n    }\n\n    .results-title {\n      font-size: 1.1rem;\n      font-weight: 700;\n      color: var(--text);\n    }\n\n    .results-title small {\n      display: block;\n      font-size: 0.8rem;\n      font-weight: 400;\n      color: var(--text3);\n      margin-top: 2px;\n    }\n\n    .download-btns {\n      display: flex;\n      gap: 8px;\n      flex-wrap: wrap;\n    }\n\n    .btn-dl {\n      padding: 8px 16px;\n      border-radius: 8px;\n      border: 1.5px solid var(--border);\n      background: white;\n      color: var(--text);\n      font-size: 0.82rem;\n      font-weight: 600;\n      cursor: pointer;\n      transition: all 0.2s;\n      font-family: \'Inter\', sans-serif;\n      display: flex; align-items: center; gap: 6px;\n    }\n\n    .btn-dl:hover {\n      border-color: var(--accent);\n      color: var(--accent);\n      background: rgba(37,99,235,0.04);\n    }\n\n    .btn-dl.pdf { border-color: #e74c3c44; color: #c0392b; }\n    .btn-dl.pdf:hover { background: #fef2f2; border-color: #c0392b; }\n\n    /* ── Stats grid ── */\n    .stats-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));\n      gap: 12px;\n      margin-bottom: 1.5rem;\n    }\n\n    .stat-card {\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: 14px;\n      padding: 1rem;\n      text-align: center;\n      box-shadow: 0 2px 8px rgba(0,0,0,0.04);\n    }\n\n    .stat-card .stat-val {\n      font-size: 1.6rem;\n      font-weight: 700;\n      line-height: 1;\n      margin-bottom: 4px;\n    }\n\n    .stat-card .stat-label {\n      font-size: 0.75rem;\n      color: var(--text3);\n      font-weight: 500;\n      text-transform: uppercase;\n      letter-spacing: 0.4px;\n    }\n\n    .stat-card.good .stat-val { color: var(--success); }\n    .stat-card.warn .stat-val { color: var(--warning); }\n    .stat-card.info .stat-val { color: var(--accent); }\n    .stat-card.gly  .stat-val { color: #7c3aed; }\n    .stat-card.pro  .stat-val { color: #0891b2; }\n\n    /* ── Plot container ── */\n    .plot-wrap {\n      background: white;\n      border: 1px solid var(--border);\n      border-radius: 16px;\n      overflow: hidden;\n      box-shadow: var(--shadow-lg);\n      margin-bottom: 1.5rem;\n    }\n\n    .plot-wrap img {\n      width: 100%;\n      height: auto;\n      display: block;\n    }\n\n    /* ── Outlier table ── */\n    .outlier-section { margin-top: 1.5rem; }\n\n    .section-title {\n      font-size: 0.9rem;\n      font-weight: 700;\n      color: var(--text);\n      margin-bottom: 0.75rem;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n    }\n\n    .badge {\n      padding: 2px 8px;\n      border-radius: 999px;\n      font-size: 0.72rem;\n      font-weight: 600;\n    }\n\n    .badge-danger { background: #fef2f2; color: var(--danger); }\n    .badge-info   { background: #eff6ff; color: var(--accent); }\n\n    .table-wrap {\n      overflow-x: auto;\n      border: 1px solid var(--border);\n      border-radius: 12px;\n    }\n\n    table {\n      width: 100%;\n      border-collapse: collapse;\n      font-size: 0.825rem;\n    }\n\n    thead th {\n      background: #f8fafc;\n      padding: 9px 14px;\n      text-align: left;\n      font-weight: 600;\n      color: var(--text2);\n      font-size: 0.775rem;\n      text-transform: uppercase;\n      letter-spacing: 0.4px;\n      border-bottom: 1px solid var(--border);\n    }\n\n    tbody tr:hover { background: #f8fafc; }\n\n    tbody td {\n      padding: 8px 14px;\n      border-bottom: 1px solid #f1f5f9;\n      color: var(--text);\n      font-family: \'JetBrains Mono\', monospace;\n      font-size: 0.8rem;\n    }\n\n    .type-badge {\n      padding: 2px 8px;\n      border-radius: 6px;\n      font-size: 0.72rem;\n      font-weight: 600;\n      font-family: \'Inter\', sans-serif;\n    }\n\n    .type-gly { background: #f3e8ff; color: #7c3aed; }\n    .type-pro { background: #e0f2fe; color: #0369a1; }\n    .type-gen { background: #fef9c3; color: #854d0e; }\n\n    /* ── Footer ── */\n    footer {\n      text-align: center;\n      padding: 1.5rem;\n      color: var(--text3);\n      font-size: 0.8rem;\n      border-top: 1px solid var(--border);\n      background: rgba(255,255,255,0.7);\n    }\n\n    /* ── Responsive ── */\n    @media (max-width: 600px) {\n      .hero h1 { font-size: 1.5rem; }\n      .input-row { flex-direction: column; }\n      .btn-analyze { width: 100%; justify-content: center; }\n    }\n  </style>\n</head>\n<body>\n\n<!-- Animated protein backbone background -->\n<canvas id="bg-canvas"></canvas>\n\n<div class="app">\n  <header>\n    <a class="logo" href="#">\n      <div class="logo-icon">🧬</div>\n      <span class="logo-text">Rama<span>Plot</span></span>\n    </a>\n    <span class="header-badge">RAMACHANDRAN ANALYZER</span>\n  </header>\n\n  <main>\n    <!-- Hero -->\n    <div class="hero">\n      <h1>Ramachandran <span>Plot Analyzer</span></h1>\n      <p>Visualize backbone torsion angles φ and ψ for protein structures. Identify favored regions, allowed regions, and outliers.</p>\n    </div>\n\n    <!-- Input Card -->\n    <div class="input-card">\n      <div class="input-tabs">\n        <button class="tab-btn active" onclick="switchTab(\'pdb-id\')">🔍 PDB ID</button>\n        <button class="tab-btn" onclick="switchTab(\'upload\')">📁 Upload File</button>\n      </div>\n\n      <!-- PDB ID Tab -->\n      <div class="tab-panel active" id="tab-pdb-id">\n        <div class="input-row">\n          <div class="input-group">\n            <label>PDB Accession Code</label>\n            <input type="text" class="input-field" id="pdb-id-input"\n                   placeholder="e.g. 1CRN, 4HHB, 1TIM..."\n                   maxlength="6" autocomplete="off"\n                   onkeydown="if(event.key===\'Enter\') analyze()"/>\n          </div>\n          <button class="btn-analyze" onclick="analyze()">\n            <span>⚡</span> Analyze\n          </button>\n        </div>\n        <p style="margin-top:10px; font-size:0.78rem; color:var(--text3);">\n          Try: <a href="#" onclick="setExample(\'1CRN\')" style="color:var(--accent);text-decoration:none;font-weight:600;">1CRN</a> (Crambin) ·\n          <a href="#" onclick="setExample(\'4HHB\')" style="color:var(--accent);text-decoration:none;font-weight:600;">4HHB</a> (Hemoglobin) ·\n          <a href="#" onclick="setExample(\'1TIM\')" style="color:var(--accent);text-decoration:none;font-weight:600;">1TIM</a> (Triose Phosphate Isomerase) ·\n          <a href="#" onclick="setExample(\'2LZM\')" style="color:var(--accent);text-decoration:none;font-weight:600;">2LZM</a> (Lysozyme)\n        </p>\n      </div>\n\n      <!-- Upload Tab -->\n      <div class="tab-panel" id="tab-upload">\n        <div class="file-drop" id="file-drop" onclick="document.getElementById(\'file-input\').click()"\n             ondragover="dragOver(event)" ondragleave="dragLeave(event)" ondrop="dropFile(event)">\n          <div class="file-drop-icon">📄</div>\n          <p><strong>Click to upload</strong> or drag & drop</p>\n          <small>Supports .pdb and .cif files</small>\n          <div class="file-name" id="file-name"></div>\n        </div>\n        <input type="file" id="file-input" accept=".pdb,.cif,.ent"\n               onchange="fileSelected(this)"/>\n        <div style="margin-top:12px; display:flex; justify-content:flex-end;">\n          <button class="btn-analyze" onclick="analyze()">\n            <span>⚡</span> Analyze\n          </button>\n        </div>\n      </div>\n    </div>\n\n    <!-- Loading -->\n    <div class="loading" id="loading">\n      <div class="spinner"></div>\n      <p>Fetching structure and calculating torsion angles…</p>\n    </div>\n\n    <!-- Error -->\n    <div class="error-box" id="error-box">\n      <span>⚠️</span>\n      <span id="error-msg">Something went wrong.</span>\n    </div>\n\n    <!-- Results -->\n    <div class="results" id="results">\n      <div class="results-header">\n        <div class="results-title">\n          Analysis Results\n          <small id="results-subtitle"></small>\n        </div>\n        <div class="download-btns">\n          <button class="btn-dl" onclick="downloadPNG()">🖼️ PNG</button>\n          <button class="btn-dl" onclick="downloadSVG()">📐 SVG</button>\n          <button class="btn-dl pdf" onclick="downloadPDF()">📄 PDF Report</button>\n        </div>\n      </div>\n\n      <!-- Stats -->\n      <div class="stats-grid" id="stats-grid"></div>\n\n      <!-- Plot -->\n      <div class="plot-wrap">\n        <img id="plot-img" src="" alt="Ramachandran Plot"/>\n      </div>\n\n      <!-- Outlier Table -->\n      <div class="outlier-section" id="outlier-section"></div>\n    </div>\n  </main>\n\n  <footer>\n    RamaPlot &nbsp;·&nbsp; Ramachandran Plot Analyzer &nbsp;·&nbsp;\n    Built with BioPython + Matplotlib &nbsp;·&nbsp; Running locally\n  </footer>\n</div>\n\n<script>\n  // ── App state ──\n  let currentResidues = [];\n  let currentTitle = \'\';\n  let currentStats = {};\n  let activeTab = \'pdb-id\';\n\n  // ── Tab switching ──\n  function switchTab(tab) {\n    activeTab = tab;\n    document.querySelectorAll(\'.tab-btn\').forEach((b, i) => {\n      b.classList.toggle(\'active\', (i === 0 && tab === \'pdb-id\') || (i === 1 && tab === \'upload\'));\n    });\n    document.querySelectorAll(\'.tab-panel\').forEach(p => p.classList.remove(\'active\'));\n    document.getElementById(\'tab-\' + tab).classList.add(\'active\');\n  }\n\n  function setExample(id) {\n    switchTab(\'pdb-id\');\n    document.getElementById(\'pdb-id-input\').value = id;\n    analyze();\n    return false;\n  }\n\n  // ── File handling ──\n  function fileSelected(input) {\n    if (input.files && input.files[0]) {\n      const fn = document.getElementById(\'file-name\');\n      fn.textContent = \'✓ \' + input.files[0].name;\n      fn.style.display = \'block\';\n    }\n  }\n\n  function dragOver(e) {\n    e.preventDefault();\n    document.getElementById(\'file-drop\').classList.add(\'drag-over\');\n  }\n\n  function dragLeave(e) {\n    document.getElementById(\'file-drop\').classList.remove(\'drag-over\');\n  }\n\n  function dropFile(e) {\n    e.preventDefault();\n    document.getElementById(\'file-drop\').classList.remove(\'drag-over\');\n    const file = e.dataTransfer.files[0];\n    if (file) {\n      const dt = new DataTransfer();\n      dt.items.add(file);\n      document.getElementById(\'file-input\').files = dt.files;\n      fileSelected(document.getElementById(\'file-input\'));\n    }\n  }\n\n  // ── Main analyze ──\n  async function analyze() {\n    showLoading(true);\n    hideError();\n    hideResults();\n\n    const formData = new FormData();\n\n    if (activeTab === \'pdb-id\') {\n      const pdbId = document.getElementById(\'pdb-id-input\').value.trim();\n      if (!pdbId) { showError(\'Please enter a PDB ID.\'); showLoading(false); return; }\n      formData.append(\'pdb_id\', pdbId);\n    } else {\n      const file = document.getElementById(\'file-input\').files[0];\n      if (!file) { showError(\'Please select a PDB or CIF file.\'); showLoading(false); return; }\n      formData.append(\'file\', file);\n    }\n\n    try {\n      const res = await fetch(\'/analyze\', { method: \'POST\', body: formData });\n      const data = await res.json();\n\n      if (!res.ok || data.error) {\n        showError(data.error || \'Analysis failed.\');\n        return;\n      }\n\n      currentResidues = data.residues;\n      currentTitle = data.title;\n      currentStats = data.stats;\n\n      renderResults(data);\n    } catch (err) {\n      showError(\'Network error: \' + err.message);\n    } finally {\n      showLoading(false);\n    }\n  }\n\n  function renderResults(data) {\n    const { stats, plot_b64, residues, title } = data;\n\n    document.getElementById(\'results-subtitle\').textContent = title;\n\n    // Stats grid\n    const grid = document.getElementById(\'stats-grid\');\n    grid.innerHTML = `\n      <div class="stat-card info">\n        <div class="stat-val">${stats.total}</div>\n        <div class="stat-label">Total Residues</div>\n      </div>\n      <div class="stat-card good">\n        <div class="stat-val">${stats.pct_favored}%</div>\n        <div class="stat-label">Favored Region</div>\n      </div>\n      <div class="stat-card ${stats.pct_outliers > 5 ? \'warn\' : \'good\'}">\n        <div class="stat-val">${stats.outliers}</div>\n        <div class="stat-label">Outliers (${stats.pct_outliers}%)</div>\n      </div>\n      <div class="stat-card gly">\n        <div class="stat-val">${stats.glycine}</div>\n        <div class="stat-label">Glycine</div>\n      </div>\n      <div class="stat-card pro">\n        <div class="stat-val">${stats.proline}</div>\n        <div class="stat-label">Proline</div>\n      </div>\n    `;\n\n    // Plot\n    document.getElementById(\'plot-img\').src = \'data:image/png;base64,\' + plot_b64;\n\n    // Outlier table\n    const outlierSection = document.getElementById(\'outlier-section\');\n    const outliers = residues.filter(r => isOutlier(r.phi, r.psi, r.resname));\n\n    if (outliers.length > 0) {\n      outlierSection.innerHTML = `\n        <div class="section-title">\n          ⚠️ Outlier Residues\n          <span class="badge badge-danger">${outliers.length} found</span>\n        </div>\n        <div class="table-wrap">\n          <table>\n            <thead>\n              <tr>\n                <th>Residue</th>\n                <th>Chain</th>\n                <th>Res #</th>\n                <th>φ (phi)</th>\n                <th>ψ (psi)</th>\n                <th>Type</th>\n              </tr>\n            </thead>\n            <tbody>\n              ${outliers.slice(0, 50).map(r => `\n                <tr>\n                  <td>${r.resname}</td>\n                  <td>${r.chain}</td>\n                  <td>${r.resid}</td>\n                  <td>${r.phi.toFixed(1)}°</td>\n                  <td>${r.psi.toFixed(1)}°</td>\n                  <td><span class="type-badge type-${r.resname === \'GLY\' ? \'gly\' : r.resname === \'PRO\' ? \'pro\' : \'gen\'}">${r.resname === \'GLY\' ? \'Glycine\' : r.resname === \'PRO\' ? \'Proline\' : \'General\'}</span></td>\n                </tr>\n              `).join(\'\')}\n            </tbody>\n          </table>\n        </div>\n        ${outliers.length > 50 ? `<p style="text-align:center;color:var(--text3);font-size:0.8rem;margin-top:8px;">Showing 50 of ${outliers.length} outliers</p>` : \'\'}\n      `;\n    } else {\n      outlierSection.innerHTML = `\n        <div style="text-align:center;padding:1.5rem;color:var(--success);font-size:0.9rem;font-weight:600;">\n          ✅ No outliers detected — all residues within allowed regions\n        </div>\n      `;\n    }\n\n    document.getElementById(\'results\').classList.add(\'active\');\n    document.getElementById(\'results\').scrollIntoView({ behavior: \'smooth\', block: \'start\' });\n  }\n\n  // Simple client-side outlier check (mirrors Python logic)\n  function isOutlier(phi, psi, resname) {\n    if (resname === \'GLY\') return false;\n    const favored = [[-63,-42,45,40],[-120,130,50,45],[-65,140,40,35]];\n    const margin = 30;\n    for (const [pc,tc,sp,st] of favored) {\n      if (Math.abs(phi-pc) < sp+margin && Math.abs(psi-tc) < st+margin) return false;\n    }\n    return true;\n  }\n\n  // ── Downloads ──\n  async function downloadPNG() {\n    const res = await fetch(\'/download_png\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({ residues: currentResidues, title: currentTitle })\n    });\n    downloadBlob(await res.blob(), \'ramachandran_plot.png\');\n  }\n\n  async function downloadSVG() {\n    const res = await fetch(\'/download_svg\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({ residues: currentResidues, title: currentTitle })\n    });\n    downloadBlob(await res.blob(), \'ramachandran_plot.svg\');\n  }\n\n  async function downloadPDF() {\n    const res = await fetch(\'/download_pdf\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({ residues: currentResidues, title: currentTitle, stats: currentStats })\n    });\n    downloadBlob(await res.blob(), \'ramachandran_report.pdf\');\n  }\n\n  function downloadBlob(blob, name) {\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement(\'a\');\n    a.href = url; a.download = name; a.click();\n    URL.revokeObjectURL(url);\n  }\n\n  // ── UI helpers ──\n  function showLoading(v) {\n    document.getElementById(\'loading\').classList.toggle(\'active\', v);\n  }\n\n  function showError(msg) {\n    const box = document.getElementById(\'error-box\');\n    document.getElementById(\'error-msg\').textContent = msg;\n    box.classList.add(\'active\');\n  }\n\n  function hideError() {\n    document.getElementById(\'error-box\').classList.remove(\'active\');\n  }\n\n  function hideResults() {\n    document.getElementById(\'results\').classList.remove(\'active\');\n  }\n\n  // ── Animated protein backbone canvas ──\n  (function() {\n    const canvas = document.getElementById(\'bg-canvas\');\n    const ctx = canvas.getContext(\'2d\');\n    let W, H, nodes, t = 0;\n\n    function resize() {\n      W = canvas.width = window.innerWidth;\n      H = canvas.height = window.innerHeight;\n      init();\n    }\n\n    function init() {\n      nodes = [];\n      const count = Math.floor((W * H) / 14000);\n      for (let i = 0; i < count; i++) {\n        nodes.push({\n          x: Math.random() * W,\n          y: Math.random() * H,\n          vx: (Math.random() - 0.5) * 0.4,\n          vy: (Math.random() - 0.5) * 0.4,\n          r: Math.random() * 3 + 2,\n          phase: Math.random() * Math.PI * 2\n        });\n      }\n    }\n\n    function draw() {\n      ctx.clearRect(0, 0, W, H);\n      t += 0.008;\n\n      // Move nodes\n      nodes.forEach(n => {\n        n.x += n.vx + Math.sin(t + n.phase) * 0.3;\n        n.y += n.vy + Math.cos(t + n.phase * 0.7) * 0.3;\n        if (n.x < 0) n.x = W;\n        if (n.x > W) n.x = 0;\n        if (n.y < 0) n.y = H;\n        if (n.y > H) n.y = 0;\n      });\n\n      // Draw backbone connections (bonds)\n      for (let i = 0; i < nodes.length; i++) {\n        for (let j = i + 1; j < nodes.length; j++) {\n          const dx = nodes[i].x - nodes[j].x;\n          const dy = nodes[i].y - nodes[j].y;\n          const dist = Math.sqrt(dx*dx + dy*dy);\n          const maxDist = 110;\n          if (dist < maxDist) {\n            const alpha = (1 - dist / maxDist) * 0.5;\n            ctx.beginPath();\n            ctx.moveTo(nodes[i].x, nodes[i].y);\n            ctx.lineTo(nodes[j].x, nodes[j].y);\n            ctx.strokeStyle = `rgba(37,99,235,${alpha})`;\n            ctx.lineWidth = dist < 55 ? 1.2 : 0.6;\n            ctx.stroke();\n          }\n        }\n      }\n\n      // Draw nodes (atoms)\n      nodes.forEach(n => {\n        ctx.beginPath();\n        ctx.arc(n.x, n.y, n.r, 0, Math.PI * 2);\n        ctx.fillStyle = `rgba(14,165,233,0.6)`;\n        ctx.fill();\n      });\n\n      requestAnimationFrame(draw);\n    }\n\n    window.addEventListener(\'resize\', resize);\n    resize();\n    draw();\n  })();\n</script>\n</body>\n</html>\n'

with open(APP_PY, 'r', encoding='utf-8') as f:
    src = f.read()

src = src.replace(
    'from flask import Flask, request, jsonify, render_template, send_file',
    'from flask import Flask, request, jsonify, send_file, Response'
)

old_route = """@app.route('/')
def index():
    return render_template('index.html')"""

new_route = """@app.route('/')
def index():
    return Response(HTML_PAGE, mimetype='text/html')"""

src = src.replace(old_route, new_route)

final = "HTML_PAGE = " + repr(HTML_PAGE) + "\n\n" + src

try:
    compile(final, 'app_embedded.py', 'exec')
except SyntaxError as e:
    print("ERROR: Syntax error:", e)
    sys.exit(1)

with open(OUT, 'w', encoding='utf-8') as f:
    f.write(final)

print(f"  app_embedded.py generated OK ({len(final):,} chars)")
